<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#0b1020">
<title>WAI Textile Automation • Demo</title>
<style>
:root{--bg:#080d18;--panel:#0e1627;--panel2:#121d31;--line:#23324b;--text:#f7f9fc;--muted:#94a3b8;--violet:#8b5cf6;--cyan:#22d3ee;--green:#22c55e;--amber:#f59e0b;--red:#ef4444;--shadow:0 28px 90px rgba(0,0,0,.38)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:radial-gradient(circle at 10% 0%,rgba(139,92,246,.18),transparent 30%),radial-gradient(circle at 92% 5%,rgba(34,211,238,.14),transparent 28%),var(--bg);color:var(--text);min-height:100vh}button,input,select{font:inherit}.wrap{max-width:1220px;margin:auto;padding:26px 16px 54px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:22px}.brand{display:flex;align-items:center;gap:12px}.logo{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;font-weight:950;background:linear-gradient(135deg,var(--violet),var(--cyan));box-shadow:0 15px 40px rgba(139,92,246,.28)}.brand b{font-size:15px;display:block}.brand span{display:block;color:var(--muted);font-size:12px;margin-top:2px}.demo{border:1px solid rgba(34,197,94,.35);color:#bbf7d0;background:rgba(34,197,94,.08);padding:8px 12px;border-radius:999px;font-size:11px;font-weight:900;white-space:nowrap}.hero{position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.07);background:linear-gradient(155deg,rgba(18,29,49,.97),rgba(8,13,24,.96));border-radius:30px;padding:34px;box-shadow:var(--shadow)}.hero:after{content:"";position:absolute;right:-80px;top:-100px;width:310px;height:310px;border-radius:50%;background:linear-gradient(145deg,rgba(139,92,246,.16),rgba(34,211,238,.05))}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:11px;color:#b9a7ff;font-weight:900}.hero h1{font-size:clamp(34px,5.4vw,64px);line-height:1.01;letter-spacing:-.045em;margin:12px 0 14px;max-width:920px}.hero p{max-width:820px;color:#bdc8d8;line-height:1.65;font-size:15px;margin:0}.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px}.chip{border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.045);padding:9px 11px;border-radius:11px;color:#dce6f2;font-size:11px;font-weight:800}.tabs{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:22px 0}.tab{border:1px solid var(--line);background:#0b1424;color:#9db0c7;border-radius:14px;padding:13px 10px;font-weight:900;cursor:pointer}.tab.active{color:white;border-color:transparent;background:linear-gradient(135deg,#6d4ee9,#118da3);box-shadow:0 12px 30px rgba(103,80,230,.22)}.grid{display:grid;grid-template-columns:1.06fr .94fr;gap:18px}.card{border:1px solid var(--line);background:rgba(14,22,39,.94);border-radius:22px;padding:21px;box-shadow:0 16px 50px rgba(0,0,0,.2)}.card h3{margin:0 0 5px;font-size:18px}.sub{font-size:12px;color:var(--muted);line-height:1.55}.phone{max-width:430px;margin:18px auto 0;background:#050910;border:1px solid #2d3a50;border-radius:34px;padding:10px;box-shadow:0 26px 75px rgba(0,0,0,.48)}.notchwrap{height:32px;display:grid;place-items:center}.notch{width:110px;height:19px;border-radius:999px;background:#020306}.screen{background:linear-gradient(180deg,#111b28,#09121d);border-radius:26px;overflow:hidden;min-height:590px}.wahead{display:flex;align-items:center;gap:10px;padding:13px 14px;background:#111f2c;border-bottom:1px solid rgba(255,255,255,.05)}.avatar{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,#7c3aed,#06b6d4);font-weight:950}.wahead b{font-size:14px}.wahead small{display:block;color:#69dfa3;margin-top:2px}.chat{padding:17px 12px;min-height:485px;display:flex;flex-direction:column;gap:9px}.msg{max-width:88%;padding:10px 11px;border-radius:12px;font-size:12px;line-height:1.48;box-shadow:0 4px 12px rgba(0,0,0,.16)}.in{background:#1a2939;border-top-left-radius:3px}.out{background:#145c4f;align-self:flex-end;border-top-right-radius:3px}.time{display:block;color:#91a4bb;font-size:9px;text-align:right;margin-top:4px}.composer{border-top:1px solid rgba(255,255,255,.06);padding:10px}.start{width:100%;border:1px solid #3b4d6c;background:#152338;color:#eef6ff;border-radius:13px;padding:13px;font-weight:900;cursor:pointer}.steps{display:grid;gap:9px;margin-top:17px}.step{display:flex;align-items:center;gap:11px;padding:11px;border:1px solid var(--line);background:#0b1525;border-radius:13px}.dot{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#162238;color:#7790ad;font-size:11px;font-weight:900;flex:0 0 auto}.step strong{font-size:12px;display:block}.step span{font-size:10px;color:var(--muted);display:block;margin-top:2px}.step.active{border-color:#6d5ce8;background:rgba(139,92,246,.08)}.step.done .dot{background:rgba(34,197,94,.14);color:#76e6a0}.quote{display:none;margin-top:15px;border:1px solid rgba(34,197,94,.3);background:linear-gradient(145deg,rgba(34,197,94,.08),rgba(139,92,246,.06));border-radius:18px;padding:17px}.quote.show{display:block}.price{font-size:38px;font-weight:950;letter-spacing:-.04em;margin:6px 0}.primary{width:100%;border:0;border-radius:12px;padding:13px;background:linear-gradient(135deg,#7c3aed,#0891b2);color:white;font-weight:900;cursor:pointer;margin-top:10px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin-bottom:15px}.kpi{padding:16px;border:1px solid var(--line);background:#0b1525;border-radius:16px}.kpi b{display:block;font-size:25px}.kpi span{font-size:10px;color:var(--muted)}.pipeline{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;overflow:auto}.stage{min-width:180px;border:1px solid var(--line);background:#0a1423;border-radius:15px;padding:12px}.stage h4{font-size:11px;margin:0 0 10px;color:#aebed1}.order{border:1px solid #283b55;background:#101d2e;border-radius:12px;padding:10px;margin-bottom:8px}.order:last-child{margin-bottom:0}.order b{font-size:11px}.order small{display:block;color:#8ea2ba;margin-top:4px;line-height:1.35}.tag{display:inline-block;margin-top:7px;font-size:9px;font-weight:900;padding:5px 7px;border-radius:8px}.t-v{background:rgba(139,92,246,.14);color:#c4b5fd}.t-c{background:rgba(34,211,238,.12);color:#a5f3fc}.t-g{background:rgba(34,197,94,.12);color:#bbf7d0}.table{overflow:auto;border:1px solid var(--line);border-radius:15px}.row{min-width:850px;display:grid;grid-template-columns:1fr .8fr .8fr .9fr .9fr .9fr;gap:8px;padding:12px 13px;border-bottom:1px solid rgba(255,255,255,.06);align-items:center;font-size:11px}.row:last-child{border-bottom:0}.row.head{background:#0a1423;color:#8fa2b8;font-weight:900}.status{display:inline-block;padding:6px 8px;border-radius:8px;font-size:9px;font-weight:900}.s1{background:rgba(139,92,246,.12);color:#c4b5fd}.s2{background:rgba(245,158,11,.12);color:#fde68a}.s3{background:rgba(34,197,94,.12);color:#bbf7d0}.formgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:15px}.field{border:1px solid var(--line);background:#0b1525;border-radius:13px;padding:12px}.field label{display:block;font-size:10px;color:#95a6bd;margin-bottom:7px;font-weight:800}.field input,.field select{width:100%;border:0;outline:0;background:transparent;color:white;font-weight:800}.calc{margin-top:15px;padding:15px;border:1px solid rgba(139,92,246,.28);background:rgba(139,92,246,.06);border-radius:16px}.calcrow{display:flex;justify-content:space-between;gap:12px;font-size:11px;color:#b7c3d3;margin-bottom:8px}.calcrow.total{font-size:17px;color:white;font-weight:950;padding-top:8px;border-top:1px solid rgba(255,255,255,.08)}.notice{margin-top:18px;border:1px solid rgba(245,158,11,.22);background:rgba(245,158,11,.06);color:#e8d4a0;border-radius:13px;padding:13px 14px;font-size:10px;line-height:1.55}.hidden{display:none}.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%) translateY(18px);background:white;color:#07101d;border-radius:12px;padding:11px 15px;font-size:11px;font-weight:900;opacity:0;transition:.22s;pointer-events:none;z-index:50}.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}
@media(max-width:900px){.wrap{padding:17px 11px 34px}.hero{padding:24px 19px;border-radius:23px}.top{align-items:flex-start}.tabs{grid-template-columns:repeat(2,1fr);position:sticky;top:7px;z-index:8;background:rgba(8,13,24,.84);backdrop-filter:blur(12px);padding:7px;border-radius:16px}.grid{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}.pipeline{grid-template-columns:repeat(5,180px)}.formgrid{grid-template-columns:1fr}.brand span{max-width:180px}.demo{font-size:9px}}
</style>
</head>
<body>
<div class="wrap">
<div class="top"><div class="brand"><div class="logo">W</div><div><b>WAI Textile Automation</b><span>Tişört Üretim & Satış Operasyon Prototipi</span></div></div><div class="demo">● DEMO ORTAMI</div></div>
<section class="hero"><div class="eyebrow">Tekstil satış ve üretim otomasyonu</div><h1>Müşteri mesajından üretim teslimatına, tek sistemde.</h1><p>WhatsApp üzerinden gelen talepleri ürün, beden, renk, baskı, adet ve termin detaylarına göre otomatik toplar; fiyatlandırma kurallarınızı uygular, teklif oluşturur ve siparişi üretim sürecine aktarır.</p><div class="chips"><span class="chip">Akıllı fiyatlandırma</span><span class="chip">WhatsApp satış asistanı</span><span class="chip">Sipariş & üretim takibi</span><span class="chip">Beden / renk / baskı yönetimi</span><span class="chip">Personel & görev takibi</span><span class="chip">Ciro & satış raporları</span></div></section>
<div class="tabs"><button class="tab active" data-tab="sales">AI Satış Akışı</button><button class="tab" data-tab="pricing">Fiyat Motoru</button><button class="tab" data-tab="orders">Üretim Paneli</button><button class="tab" data-tab="dashboard">Yönetici Paneli</button></div>
<section id="salesTab"><div class="grid"><div class="card"><h3>WhatsApp Müşteri Akışı</h3><div class="sub">Müşteri genel cevap almak yerine siparişe götüren sorularla ilerler.</div><div class="phone"><div class="notchwrap"><div class="notch"></div></div><div class="screen"><div class="wahead"><div class="avatar">AI</div><div><b>WAI Tekstil Satış Asistanı</b><small>● çevrimiçi</small></div></div><div class="chat" id="chat"><div class="msg in">Merhaba 👋 Ürün, adet ve baskı detaylarını paylaşırsanız size hızlıca teklif hazırlayabilirim.<span class="time">21:34</span></div></div><div class="composer"><button class="start" id="startBtn">▶ Örnek Müşteri Talebini Başlat</button></div></div></div></div><div class="card"><h3>Satış Motoru</h3><div class="sub">Müşteri bilgileri toplandıkça sistem teklif için gerekli alanları tamamlar.</div><div class="steps"><div class="step" id="s1"><div class="dot">1</div><div><strong>Ürün tipi</strong><span>Oversize tişört</span></div></div><div class="step" id="s2"><div class="dot">2</div><div><strong>Adet & beden dağılımı</strong><span>200 adet • S / M / L / XL</span></div></div><div class="step" id="s3"><div class="dot">3</div><div><strong>Renk & kumaş</strong><span>Siyah • 30/1 penye</span></div></div><div class="step" id="s4"><div class="dot">4</div><div><strong>Baskı detayları</strong><span>Ön göğüs • tek renk serigrafi</span></div></div><div class="step" id="s5"><div class="dot">5</div><div><strong>Termin & fiyat</strong><span>Kurallar uygulanıp teklif hazırlanır</span></div></div></div><div class="quote" id="quote"><div class="sub">200 adet • Siyah Oversize • Ön göğüs baskı</div><div style="font-size:11px;color:#a8bad0;margin-top:7px">Birim fiyat</div><div class="price">186 TL</div><div style="font-size:11px;color:#79e4a7;font-weight:900">✓ Toplam teklif: 37.200 TL</div><button class="primary" id="approveBtn">Siparişi Üretime Aktar</button></div></div></div></section>
<section id="pricingTab" class="hidden"><div class="grid"><div class="card"><h3>Dinamik Fiyatlandırma Motoru</h3><div class="sub">Fiyat kurallarını panelden değiştirirsiniz; yapay zekâ müşteriye aynı kurallarla hesaplama yapar.</div><div class="formgrid"><div class="field"><label>Ürün</label><select id="product"><option value="145">Oversize Tişört</option><option value="125">Regular Tişört</option><option value="190">Polo Yaka</option></select></div><div class="field"><label>Adet</label><input id="qty" type="number" min="25" value="200"></div><div class="field"><label>Baskı Türü</label><select id="print"><option value="22">Tek Renk Serigrafi</option><option value="38">DTF Baskı</option><option value="48">Nakış</option></select></div><div class="field"><label>Termin</label><select id="deadline"><option value="1">Standart</option><option value="1.12">Acil Üretim (+%12)</option></select></div></div><div class="calc"><div class="calcrow"><span>Ürün baz fiyatı</span><b id="baseText">145 TL</b></div><div class="calcrow"><span>Baskı maliyeti</span><b id="printText">22 TL</b></div><div class="calcrow"><span>Adet indirimi</span><b id="discountText">-%5</b></div><div class="calcrow total"><span>Birim fiyat</span><span id="unitText">159 TL</span></div><div class="calcrow total"><span>Toplam</span><span id="totalText">31.800 TL</span></div></div></div><div class="card"><h3>Kurallar Sizde</h3><div class="sub">Canlı sistemde aşağıdaki gibi kurallar eklenebilir.</div><div class="steps"><div class="step done"><div class="dot">✓</div><div><strong>Adet bazlı iskonto</strong><span>100+, 250+, 500+, 1000+ kademeleri</span></div></div><div class="step done"><div class="dot">✓</div><div><strong>Baskı farkları</strong><span>Serigrafi, DTF, nakış, çok renk</span></div></div><div class="step done"><div class="dot">✓</div><div><strong>Özel üretim farkı</strong><span>Kumaş, gramaj, yaka, etiket, paketleme</span></div></div><div class="step done"><div class="dot">✓</div><div><strong>Acil termin farkı</strong><span>Belirlediğiniz yüzde otomatik uygulanır</span></div></div><div class="step done"><div class="dot">✓</div><div><strong>Bayi / toptan fiyatı</strong><span>Müşteri tipine özel fiyat listesi</span></div></div></div></div></div></section>
<section id="ordersTab" class="hidden"><div class="card"><h3>Sipariş & Üretim Merkezi</h3><div class="sub">Satıştan çıkan sipariş, üretim hattında hangi aşamada olduğu görülecek şekilde ilerler.</div><div class="pipeline" style="margin-top:16px"><div class="stage"><h4>TEKLİF</h4><div class="order"><b>#TK-1048 • 200 adet</b><small>Siyah Oversize<br>Ön göğüs baskı</small><span class="tag t-v">37.200 TL</span></div><div class="order"><b>#TK-1051 • 80 adet</b><small>Beyaz Regular<br>DTF baskı</small><span class="tag t-v">14.480 TL</span></div></div><div class="stage"><h4>ONAYLANDI</h4><div class="order"><b>#TK-1044 • 350 adet</b><small>Lacivert Polo<br>Nakış</small><span class="tag t-c">Müşteri onayladı</span></div></div><div class="stage"><h4>ÜRETİMDE</h4><div class="order"><b>#TK-1039 • 500 adet</b><small>Siyah Oversize<br>2 renk serigrafi</small><span class="tag t-c">Baskıda</span></div><div class="order"><b>#TK-1041 • 120 adet</b><small>Ekru Regular<br>DTF baskı</small><span class="tag t-c">Dikimde</span></div></div><div class="stage"><h4>PAKETLEME</h4><div class="order"><b>#TK-1034 • 220 adet</b><small>Beyaz Oversize<br>Özel etiket</small><span class="tag t-g">Kontrol tamamlandı</span></div></div><div class="stage"><h4>TESLİMAT</h4><div class="order"><b>#TK-1028 • 1000 adet</b><small>Siyah Regular<br>Kurumsal baskı</small><span class="tag t-g">Kargoya hazır</span></div></div></div></div></section>
<section id="dashboardTab" class="hidden"><div class="card"><h3>Yönetici Operasyon Paneli</h3><div class="sub">Satış, teklif, üretim ve ciroyu tek ekranda takip edin.</div><div class="kpis" style="margin-top:16px"><div class="kpi"><b>128</b><span>Bu ay gelen talep</span></div><div class="kpi"><b>64</b><span>Hazırlanan teklif</span></div><div class="kpi"><b>27</b><span>Aktif sipariş</span></div><div class="kpi"><b>₺684K</b><span>Aylık sipariş hacmi</span></div></div><div class="table"><div class="row head"><div>Müşteri</div><div>Ürün</div><div>Adet</div><div>Tutar</div><div>Durum</div><div>Sorumlu</div></div><div class="row"><div>Atlas Organizasyon</div><div>Oversize</div><div>500</div><div>96.500 TL</div><div><span class="status s2">Üretimde</span></div><div>Mehmet</div></div><div class="row"><div>Nova Ajans</div><div>Regular</div><div>200</div><div>34.800 TL</div><div><span class="status s1">Teklif</span></div><div>Selin</div></div><div class="row"><div>Zen Tekstil</div><div>Polo Yaka</div><div>350</div><div>82.250 TL</div><div><span class="status s3">Onaylandı</span></div><div>Burak</div></div><div class="row"><div>Vera Events</div><div>Oversize</div><div>120</div><div>22.560 TL</div><div><span class="status s3">Paketleme</span></div><div>Ayşe</div></div></div></div></section>
<div class="notice">Bu sayfa entegrasyon öncesi operasyon prototipidir. Canlı sistemde ürünleriniz, fiyat kurallarınız, kumaş/baskı seçenekleriniz, personel yapınız ve üretim adımlarınız size özel tanımlanır.</div>
</div><div class="toast" id="toast"></div>
<script>
const tabs=document.querySelectorAll('.tab');const sections={sales:document.getElementById('salesTab'),pricing:document.getElementById('pricingTab'),orders:document.getElementById('ordersTab'),dashboard:document.getElementById('dashboardTab')};tabs.forEach(b=>b.onclick=()=>{tabs.forEach(x=>x.classList.remove('active'));b.classList.add('active');Object.values(sections).forEach(s=>s.classList.add('hidden'));sections[b.dataset.tab].classList.remove('hidden')});
const chat=document.getElementById('chat');const start=document.getElementById('startBtn');const q=document.getElementById('quote');let running=false;function msg(text,out=false){const d=document.createElement('div');d.className='msg '+(out?'out':'in');d.innerHTML=text+'<span class="time">21:35</span>';chat.appendChild(d);chat.scrollTop=chat.scrollHeight}function mark(id,state){const e=document.getElementById(id);e.classList.remove('active','done');e.classList.add(state)}
start.onclick=async()=>{if(running)return;running=true;start.textContent='İşlem devam ediyor...';const wait=t=>new Promise(r=>setTimeout(r,t));msg('200 adet siyah oversize tişört istiyorum, ön göğüste logomuz olacak.',true);mark('s1','active');await wait(650);mark('s1','done');msg('Tabii. Beden dağılımını ve baskı türünü netleştirelim. S/M/L/XL dağılımınız nasıl olsun?');await wait(650);msg('S:30, M:70, L:70, XL:30. Tek renk baskı.',true);mark('s2','done');mark('s3','active');await wait(650);mark('s3','done');mark('s4','done');msg('Tamamdır. 30/1 penye siyah oversize, 200 adet, tek renk ön göğüs baskı olarak hesaplıyorum. Standart teslim süreniz uygun mu?');await wait(650);msg('Evet uygun.',true);mark('s5','active');await wait(700);mark('s5','done');q.classList.add('show');msg('Teklifiniz hazır ✅ Birim 186 TL, toplam 37.200 TL. Onay verirseniz siparişi üretim planına aktarabilirim.');start.textContent='Demo tamamlandı';};
function calc(){const base=+document.getElementById('product').value,pr=+document.getElementById('print').value,qty=Math.max(25,+document.getElementById('qty').value||25),deadline=+document.getElementById('deadline').value;let disc=qty>=1000?.14:qty>=500?.10:qty>=250?.07:qty>=100?.05:0;let unit=(base+pr)*(1-disc)*deadline;document.getElementById('baseText').textContent=base+' TL';document.getElementById('printText').textContent=pr+' TL';document.getElementById('discountText').textContent='-%'+Math.round(disc*100);document.getElementById('unitText').textContent=Math.round(unit)+' TL';document.getElementById('totalText').textContent=(Math.round(unit*qty)).toLocaleString('tr-TR')+' TL'}['product','print','qty','deadline'].forEach(id=>document.getElementById(id).addEventListener('input',calc));calc();
function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}document.getElementById('approveBtn').onclick=()=>toast('Sipariş üretim planına aktarıldı ✓');
</script>
</body></html>